/**
 * AB7 (AX16) + ED10 (EB4) — the shop service worker, served at
 * /shop-push-sw.
 *
 * ONE worker for the "/shop/" scope (the
 * `Service-Worker-Allowed: /shop/` header below permits a script
 * served from the app root to claim that scope). It began as
 * push-only (AB7); ED10 extended the SAME script with an app
 * shell — fetch caching + offline fallback — without touching
 * the push/notificationclick handlers. The script itself is
 * generated by lib/shop-sw (buildShopWorkerScript) so specs can
 * pin its rules; registration (ShopPushPrompt / push-panel,
 * "/shop-push-sw" + scope "/shop/") is unchanged.
 *
 * The dashboard PWA worker (public/sw.js, root scope "/") is a
 * separate worker and is NOT modified by ED10.
 */
// Relative import (not "@/lib/...") on purpose: vitest has no "@"
// alias in this app, and this route is unit-tested directly
// (route.test.ts) — the same pattern components/MediaImage uses.
import { buildShopWorkerScript } from "../../lib/shop-sw";

const WORKER_JS = buildShopWorkerScript();

export async function GET(): Promise<Response> {
  return new Response(WORKER_JS, {
    headers: {
      "Content-Type": "application/javascript; charset=utf-8",
      "Service-Worker-Allowed": "/shop/",
      "Cache-Control": "no-cache",
    },
  });
}
